
function setupCanvas(container) {
    const canvas = container.querySelector('canvas');
    const ctx = canvas.getContext('2d');
    const toggleBtn = container.querySelector('label');
    
    const clearBtn = document.createElement('button');
    clearBtn.type = 'button';
    clearBtn.textContent = 'Apagar Assinatura';
    clearBtn.className = 'btn--form';
    clearBtn.style.display = 'none';
    container.appendChild(clearBtn);


    const sairBtn = document.createElement('button');
    sairBtn.type = 'button';
    sairBtn.textContent = 'Fechar assinatura';
    sairBtn.className = 'btn--form';
    sairBtn.style.display = 'none';
    container.appendChild(sairBtn);

    let isDrawing = false;
    let lastX = 0;
    let lastY = 0;

    function setupContext() {
        ctx.lineJoin = 'round';
        ctx.lineCap = 'round';
        ctx.strokeStyle = '#000000';
        ctx.lineWidth = 3;
    }


    function resizeCanvas() {
        if (!canvas.hasAttribute('hidden')) {
            canvas.width = canvas.offsetWidth;
            canvas.height = canvas.offsetHeight;
            setupContext();
        }
    }

    toggleBtn.addEventListener('click', () => {
        canvas.toggleAttribute('hidden');
        if (canvas.hasAttribute('hidden')) {
            clearBtn.style.display =  'none';
            sairBtn.style.display =  'none';
        }else{
            clearBtn.style.display =  'block';
            sairBtn.style.display =  'block';
        }
        
        // Rotate screen

        if( /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent) ) {
            const body = document.querySelector('body');
                if(body.requestFullscreen) {
                    body.requestFullscreen();
                }else if(body.webkitRequestFullScreen) {
                    body.webkitRequestFullScreen();
                }
                
                if (screen.orientation && screen.orientation.lock) {
                    screen.orientation.lock("landscape-primary")
                        .then(() => console.log('landscape-primary'))
                        .catch((error) => {
                            console.log('Erro na rotaçãoi :', error);
                        });
                    
                }
        }
        resizeCanvas();
              

    });
    clearBtn.addEventListener('click', () => {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
    });
    sairBtn.addEventListener('click', ()=> {
        if (screen.orientation && screen.orientation.unlock) {
            screen.orientation.unlock();
        }
        if (document.fullscreenElement || document.webkitFullscreenElement) {
            if (document.exitFullscreen) {
                document.exitFullscreen();
            } else if (document.webkitExitFullscreen) {
                document.webkitExitFullscreen();
            }
        }
        
        canvas.setAttribute('hidden', 'true');
        clearBtn.style.display = 'none';
        sairBtn.style.display = 'none';

        });
    function getPosition(e) {
        const rect = canvas.getBoundingClientRect();
        

        const clientX = e.touches ? e.touches[0].clientX : e.clientX;
        const clientY = e.touches ? e.touches[0].clientY : e.clientY;
        
        return {
            x: clientX - rect.left,
            y: clientY - rect.top
        };
    }

    // --- Funções de desenho ---

    function startDrawing(e) {
        const pos = getPosition(e);
        isDrawing = true;
        lastX = pos.x;
        lastY = pos.y;
    }

    function draw(e) {
        if (!isDrawing) return;
        
        e.preventDefault(); 
        
        const pos = getPosition(e);

        ctx.beginPath();
        ctx.moveTo(lastX, lastY);
        ctx.lineTo(pos.x, pos.y);
        ctx.stroke();

        lastX = pos.x;
        lastY = pos.y;
    }

    function stopDrawing() {
        isDrawing = false;
    }



    

    
    canvas.addEventListener('touchstart', startDrawing);
    canvas.addEventListener('touchmove', draw, { passive: false }); 
    canvas.addEventListener('touchend', stopDrawing);
    canvas.addEventListener('touchcancel', stopDrawing);


    canvas.addEventListener('mousedown', startDrawing);
    canvas.addEventListener('mousemove', draw);
    canvas.addEventListener('mouseup', stopDrawing);
    canvas.addEventListener('mouseout', stopDrawing); 
}

const containers = document.querySelectorAll('.assinatura');
if (containers.length >= 2) {
    const cliente = containers[0];
    const responsavel = containers[1];

    setupCanvas(cliente);
    setupCanvas(responsavel);
}